import runpy,json
from pathlib import Path
S=Path(__file__).resolve().parents[1];e=runpy.run_path(str(S/'work/write_superdaily_early.py'));add=e['add'];out=e['out'];cost=e['cost']
add('HDMSL','同步期現價差外帶反向進一口，以較內側價差帶或價格停損／移停退出，訊號優先於價格保護。','價差與配對',['只支援TX且需同分鐘現貨，09:00現貨略過；期貨open>現貨+進場距離空一口，<現貨−進場距離多一口。','出場上帶若嚴格落在兩進場外帶內才啟用內帶退出：多open>現貨−出場距離平，空open<現貨+出場距離平；不符合此距離關係時等相反外帶反手。'],['價差目標部位改變就先執行並continue，該根不再價格風控；若目標未改，持倉才查固定停損或已有移停中的直停／回撤。','多固定損只看open，空固定損看high；直停只在已有移停線時檢查。更新線以open換距離，當根close穿新線可立即出。','換倉當根close平掉並continue，不自動續開；末筆open強平。'],[cost,'保護判斷用OHLC，但函式雖算線價／跳空成交價，實際都呼叫共用策略出場而未傳該price，所以紀錄一律open。','沒有ValidKBAR過濾；同期現貨缺根連價格保護也被continue跳過。'],['內帶%以當筆現貨價換算，負數可把出場門檻越過中線；若絕對值太大則取消內帶退出。','移停只要求新線不同，未保證有利方向推進；不能照一般只上移／下移的追蹤停損理解。','缺現貨時維持部位但不查風控，且直停未啟移前無效，這些都會影響實際退出時序。'],{'進場多空比':'現貨open上下對稱距離，嚴格超外帶反向進場，%或點數。','出場多空比':'內帶距離，0中線，負值可過中線才出；只有出場上帶在兩進場外帶之間才使用。','停損比':'以實際進場open設定固定價，%或點數；多用open、空用high判，但成交仍open。','啟動移停比':'進場價加減距離，high/low觸發後改啟移基準為當根open。','移停拉回比':'以更新當根open換%或點數的新線，未作單向限制；close可同根觸發但仍open成交。','直接停利比':'只在已有移停線時以high/low判斷，實際紀錄open，不是算出的直停線價。'})
add('HDM宇','期現價差反向一口交易，加紅棒多單濾網；原方向虧損達距離可切成獨立反向狀態並另設停損。','價差與反手',['在固定可處理日內時窗且KBAR相位通過時，正價差>=空距離先空，否則逆價差<=負多距離才多。多單可再要求目前open−08:45open>=R點。','普通多持有若出現正價差空，先轉普通空；否則低於入場−X距離轉反向空。普通空對稱，先新逆價差多，否則高於入場+Y轉反向多。'],['反向多／空先以反向入場價加減K距離判停損回空手；若行情又符合與持倉同向的普通價差訊號，只切回普通狀態並重設內部_entry_price，不增減持倉。','跨曆日最後一根只平反向倉，普通價差倉可隔夜；每日DD可在前根close零滑價平開普通倉。相鄰根合約不同或資料末筆，全按當根open平。'],[cost,'現貨搜尋可回傳本次掃過的最近較早一筆，不必同分鐘；但若本次沒彈出舊資料也無精確根，回null，並非永久沿用上一現貨。','每次目標限±1，反手兩口。普通狀態轉反向也按新價記真交易，但反向轉普通同向只重設內部風控價。'],['固定日內時窗之外連反向停損也不檢查，只剩日界／換約／末筆退出。08:45缺根時日開盤可能沿舊值或初值，紅棒濾網受影響。','反向轉普通重設風控入場價但沒有實際平開紀錄，內部風控基準與報表原持倉成本會不同。','只提供可寫參數清單；原碼其他唯讀方向／時間／損失欄位不能由此推定都有實際停機判斷。'],{'多進場比':'現貨open減%或點數為逆價差多門檻，含等號；還可配紅棒濾網。','空進場比':'現貨open加%或點數為正價差空門檻，含等號，空側先判。','多單紅棒':'啟用則目前期貨open−08:45記錄open至少R點才允許普通逆價差多。','多單紅棒R點以上':'固定價格點數，不是紅K根數或百分比；以當日08:45open作基準。','逆價差反向X點空':'普通多入場價減此%或點數，未先出現正價差時觸發轉反向空。','正價差反向Y點多':'普通空入場價加此%或點數，未先出現逆價差時觸發轉反向多。','反向停損K點':'反向狀態實際建立價加減的%或點數風險線；只在日內時窗及KBAR通過且有可用現貨時檢查。','KBAR間隔ex':'日內價差與反向損線都取分鐘相位，日界／換約／末筆退出不受相位。','開始交易時間':'ValidKBAR分鐘相位原點，與原碼固定日內處理時窗不是同一欄。','計算DD方式':'每日計算在跨曆日最後一根對普通持倉插零滑價close平開；反向倉則真平。'})
add('HBDS','每日首根建價格基準，按上下突破做多空；H模式可用前日價差直接入場，之後固定停損可反手重進。','每日突破與價差',['每個曆日首根open建一條基準，靠近啟動基準的濾網會略過。突破模式上／下距離對稱，通過KBAR後OHLC全部覆為open。','同根只許第一條空手線突破，其餘觸價線停止；跳空先把整組基準平移到當筆價再建風控。','H指標模式取前一日期貨close<同日現貨close則多，否則空，於新日首根直接進；多用新根open，空卻用新根close。無前日資料則退回價格突破。'],['固定停損退出，已進恰等上限時停止，否則可同根只檢查另一方向再進；未達反向門檻則等後續報價。','直停只在已有移停線時生效，優先於移停退出；保護都以覆成open的價格判斷。達啟移後從有利價減／加距離建線。','迴圈結束只是把啟動子項標停止並移到停止清單，沒有新增資料末端平倉紀錄；換約仍可平舊開新一口並偏移基準與線價。'],[cost,'舊子項先反序處理，日界再新增新線，價格突破新線當根也執行；H直接入場不套用單一策略的KBAR篩選。','已進在每次新倉加一，上限在退出時用==判；0不是禁止進場而可能一直不達停止條件。'],['沒有末筆強平，故最後停止清單不等於報表已平所有倉。H模式空側同根close可能晚於多側open，不能描述成完全相同的開盤成交。','H資料搜尋while移除舊現貨後未每次檢查Count，資料耗盡可越界；不是所有缺日都安全退回突破。'],{'進場模式':'開盤突破建立上下價帶等待觸發；H指標取前日收盤期現比較新日直接進，資料不足則回突破。','多空進場比':'日首open上下對稱%或點數距離，按商品最小單位Round。','最多進場次數':'每子項已進次數，退出時==才停止；固定停損可重進，0未當禁入。','BD線濾網點':'新日首open距任何啟動基準嚴格小於此點數就不建立，等於仍建。','停損比':'每次突破／H入場價加減%或點數固定損；突破核心以open逐根觸發。','啟動移停比':'入場價加減有利距離，通過後開始推移追蹤線。','移停拉回比':'從有利價格減／加距離，百分比基準是多／空目標價，非每次極值本身。','直接停利比':'入場價加減距離，僅移停已存在時檢查，未啟移前不直接停利。','KBAR間隔ex':'一般突破與舊倉保護依分鐘相位過濾；H新日直接進不走此過濾。','開始交易時間':'ValidKBAR相位起點，不限制每日首根建線或H直接進場。'})
(S/'analysis/SuperDaily.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print('Wrote Daily HDMSL/HDM宇/HBDS')
